handleEvent(event) {
  switch (event.type) {
    case "keyup":
      this.#handleKeyboard(event);
      break;
    case "keypress":
    case "keydown":
      this.#handleKeyboard(event);
      if (event.type === "keydown") {
        this.#closeByKeyboard(event);
      }
      break;
  }
}
